#let proxy_meta_line(loopback: false) = {
  let data = proxy_data(loopback: loopback)
  let m = data.meta
  text(size: 8pt, fill: gray)[
    記録日 #m.date · サーバー #m.host · #m.cpu ·
    #if not loopback { [負荷生成器 #data.generator.host · #data.generator.cpu ·] }
    Sibunaリビジョン #raw(m.git.slice(0, 12)) ·
    Zig #m.zig · BunkerWeb #data.bunkerweb.version ·
    #if data.at("anubis", default: none) != none { [#data.anubis.version ·] }
    #data.load.threads 負荷スレッド、#data.load.connections 接続 ·
    #data.load.seconds 秒 × #data.load.repetitions ラウンド、ウォームアップ #data.load.warmup 秒
  ]
}

